SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明英宗在南郊祭祀天地", "description": "天顺六年正月丁未，明英宗朱祁镇在南郊举行祭祀天地的大典。", "start_year": 1462, "end_year": 1462, "time_original": "天顺六年正月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "297cc1ac-42fb-5088-ae9b-ab8728b3d9af"}, {"title": "孛来派遣使者入贡", "description": "天顺六年正月戊申，孛来派遣使者向明廷进贡。", "start_year": 1462, "end_year": 1462, "time_original": "天顺六年正月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2149b7b4-68f5-53bc-a593-b7bf640548e0"}, {"title": "明廷传谕孛来", "description": "天顺六年二月癸酉，明廷向孛来传达谕令。", "start_year": 1462, "end_year": 1462, "time_original": "天顺六年二月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ce35e219-00fa-5e26-b0e0-12047a58120a"}, {"title": "明廷召冯宗等人返回", "description": "天顺六年三月癸丑，明廷召此前受命防守河西的冯宗等人返回。", "start_year": 1462, "end_year": 1462, "time_original": "天顺六年三月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e495351d-f9a8-5861-a8fb-71e014d55197"}, {"title": "明廷豁免河南灾区秋粮", "description": "天顺六年四月壬申，朝廷免除河南受灾地区应缴的秋粮。", "start_year": 1462, "end_year": 1462, "time_original": "天顺六年四月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c48b9655-9827-57c4-a74d-40f2d0007909"}, {"title": "颜彪领兵平定两广多处起事", "description": "天顺六年五月庚子，《明史》本纪记颜彪率军平定两广多处起事的瑶民。", "start_year": 1462, "end_year": 1462, "time_original": "天顺六年五月庚子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "507f941a-7f99-5d05-b84c-4cbdf030c12c"}, {"title": "明廷豁免陕西灾区秋粮", "description": "天顺六年五月己未，朝廷免除陕西受灾地区应缴的秋粮。", "start_year": 1462, "end_year": 1462, "time_original": "天顺六年五月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "58467b5a-a915-5128-94d0-5ff2b650cb39"}, {"title": "淮王朱祁铨入朝", "description": "天顺六年六月戊辰，淮王朱祁铨进京朝见明英宗。", "start_year": 1462, "end_year": 1462, "time_original": "天顺六年六月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0fd54170-4e1e-58d1-9756-8b287d691009"}, {"title": "淮安发生海水泛滥", "description": "天顺六年七月，本纪记淮安发生海水泛滥。", "start_year": 1462, "end_year": 1462, "time_original": "天顺六年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ea6da934-99a9-5049-8d07-b84af48d6e96"}, {"title": "皇太后孙氏去世", "description": "天顺六年九月乙未，皇太后孙氏去世。下文按她的谥号称孝恭章皇后。", "start_year": 1462, "end_year": 1462, "time_original": "天顺六年九月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bfdacdfe-5bfd-5905-a446-91f1b48c3c3e"}, {"title": "明廷安葬孝恭章皇后孙氏", "description": "天顺六年十一月甲午，明廷安葬孝恭章皇后孙氏。", "start_year": 1462, "end_year": 1462, "time_original": "天顺六年十一月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e53ad539-f7de-5f43-9512-aa49a3674b14"}, {"title": "琉球中山、哈密、乌斯藏和暹罗入贡", "description": "天顺六年，琉球中山、哈密、乌斯藏和暹罗向明廷进贡。 按原历纪年，事情发生在公元1462至1463年之间。", "start_year": null, "end_year": null, "time_original": "天顺六年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ef316385-8055-51a7-a09f-966971b69f0e"}]'::jsonb)
